public function editShipping($order_id, $data) {
        $this->db->query("UPDATE `" . DB_PREFIX . "order` set shipping_firstname = '" . $this->db->escape($data['firstname']) . "', shipping_lastname = '" . $this->db->escape($data['lastname']) . "', shipping_company = '" . $this->db->escape($data['company']) . "', shipping_address_1 = '" . $this->db->escape($data['address_1']) . "', shipping_address_2 = '" . $this->db->escape($data['address_2']) . "', shipping_city = '" . $this->db->escape($data['city']) . "', shipping_postcode = '" . $this->db->escape($data['postcode']) . "', shipping_country = '" . $this->db->escape($data['country']) . "', shipping_country_id = '" . (int)$data['country_id'] . "', shipping_zone = '" . $this->db->escape($data['zone']) . "', shipping_zone_id = '" . (int)$data['zone_id'] . "', shipping_address_format = '" . $this->db->escape($data['address_format']) . "', shipping_custom_field = '" . $this->db->escape(json_encode($data['custom_field'])) . "',date_modified = NOW() WHERE order_id = '" . (int)$order_id . "'");
    }
    public function editPayment($order_id, $data) {
        $this->db->query("UPDATE `" . DB_PREFIX . "order` SET payment_firstname = '" . $this->db->escape($data['firstname']) . "', payment_lastname = '" . $this->db->escape($data['lastname']) . "', payment_company = '" . $this->db->escape($data['company']) . "', payment_address_1 = '" . $this->db->escape($data['address_1']) . "', payment_address_2 = '" . $this->db->escape($data['address_2']) . "', payment_city = '" . $this->db->escape($data['city']) . "', payment_postcode = '" . $this->db->escape($data['postcode']) . "', payment_country = '" . $this->db->escape($data['country']) . "', payment_country_id = '" . (int)$data['country_id'] . "', payment_zone = '" . $this->db->escape($data['zone']) . "', payment_zone_id = '" . (int)$data['zone_id'] . "', payment_address_format = '" . $this->db->escape($data['address_format']) . "', date_modified = NOW() WHERE order_id = '" . (int)$order_id . "'");

    }
    public function editCustomer($order_id, $data) {
        $this->db->query("UPDATE `" . DB_PREFIX . "order` SET customer_id = '" . (int)$data['customer_id'] . "', customer_group_id = '" . (int)$data['customer_group_id'] . "', firstname = '" . $this->db->escape($data['firstname']) . "', lastname = '" . $this->db->escape($data['lastname']) . "', email = '" . $this->db->escape($data['email']) . "', telephone = '" . $this->db->escape($data['telephone']) . "', date_modified = NOW() WHERE order_id = '" . (int)$order_id . "'");
    }
